"""Unit tests for Z3Exception fix in pipeline, batch_call, and z3_maxsat."""
import sys
sys.path.insert(0, '/root/symb_invariant_consensus')

from sica.pipeline import SICAPipeline
from sica.trace_generator import MockGenerator
from sica.constraint_extractor import ConstraintExtractor, MockLLM
from sica.z3_maxsat import parse_z3_formula

class FailGen:
    def generate(self, p, k=12): raise RuntimeError('timeout')

class FailExt:
    domain = 'math'
    def extract_batch(self, t): raise ValueError('z3 error')

class FailExtBadStr:
    domain = 'math'
    def extract_batch(self, t):
        class Bad(Exception):
            def __str__(self): raise RuntimeError('broken')
        raise Bad('x')

def test_trace_gen_failure():
    p = SICAPipeline(trace_generator=FailGen(), constraint_extractor=ConstraintExtractor(llm=MockLLM()), k=3)
    r = p.run_single({'problem': 't', 'answer': '1', 'dataset': 'math'})
    assert 'total_s' in r['timing'], 'timing must contain total_s'
    assert r['error'] == 'timeout'

def test_extraction_failure_sc_fallback():
    p = SICAPipeline(trace_generator=MockGenerator(), constraint_extractor=FailExt(), k=3)
    r = p.run_single({'problem': 't', 'answer': '7', 'dataset': 'math'})
    assert 'total_s' in r['timing']
    assert len(r.get('traces', [])) > 0, 'cached traces must be preserved'
    assert r.get('answer') == '7', 'should fall back to SC answer'

def test_exception_with_broken_str():
    p = SICAPipeline(trace_generator=MockGenerator(), constraint_extractor=FailExtBadStr(), k=3)
    r = p.run_single({'problem': 't', 'answer': '7', 'dataset': 'math'})
    assert 'total_s' in r['timing']
    assert r.get('error') == 'Bad'

def test_abs_in_z3_parser():
    assert parse_z3_formula('abs(x - 5) <= 3') is not None
    assert parse_z3_formula('abs(a - b) == 0') is not None

def test_standard_arithmetic():
    assert parse_z3_formula('a + b == 10') is not None
    assert parse_z3_formula('a**2 + b**2 == 100') is not None
    assert parse_z3_formula('a != b') is not None
    assert parse_z3_formula('a > 0') is not None

